file.content:
.cm-ai-suggestion {
  background: rgb(241 241 243 / 0.03);
}

.cm-ai-suggestion.cm-ai-active {
  background: var(--color-fill);
}

.cm-ai-refine-failed {
  text-decoration: underline dotted var(--color-danger);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.cm-ai-deleted {
  color: var(--color-ink-faint);
  text-decoration: line-through;
  text-decoration-color: var(--color-ink-faint);
}

.cm-ai-inserted,
.cm-ai-replacement ins {
  color: var(--color-accent-soft);
  background: var(--color-accent-tint);
  text-decoration: none;
  white-space: pre-wrap;
}

.cm-ai-inserted-separated {
  margin-left: 0.3em;
}

.cm-ai-replacement {
  margin: 0.2rem 0 0.9rem;
  padding: 0.35rem 0.75rem;
  background: var(--color-accent-tint);
  color: var(--color-accent-soft);
  white-space: pre-wrap;
}

.cm-ai-replacement ins {
  background: transparent;
}

.cm-ai-target-preview {
  background: var(--color-accent-tint);
}

.cm-ai-pending,
.cm-ai-refining {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    transparent 38%,
    var(--color-shimmer) 50%,
    transparent 62%,
    transparent 100%
  );
  background-size: 300% 100%;
  animation: cm-ai-shimmer 1.8s linear infinite;
}

@keyframes cm-ai-shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cm-ai-pending,
  .cm-ai-refining {
    animation: none;
    background-image: none;
    background-color: var(--color-shimmer);
  }
}

.cm-ai-failed {
  text-decoration: underline wavy var(--color-danger);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.cm-ai-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.3rem 0 0.9rem;
  padding: 0.5rem 0.75rem;
  background: var(--color-danger-tint);
  color: var(--color-danger);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  line-height: 1.45;
}

.cm-ai-error-actions {
  display: flex;
  flex: none;
  gap: 0.4rem;
}

.cm-editor .cm-tooltip.cm-ai-bubble,
.cm-editor .cm-tooltip.cm-ai-card {
  z-index: 20;
  border: 0;
  background: var(--color-raised);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  line-height: 1.4;
  box-shadow: 0 8px 28px rgb(0 0 0 / 0.5);
  animation: cm-ai-fade-in 120ms ease-out;
}

.cm-editor .cm-tooltip.cm-ai-bubble {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(26rem, 90vw);
  padding: 0.5rem;
