import { useCallback, useRef, useState } from 'react'
import type { ReviewControls } from '../editor/review-controls'
import { idleReviewStatus, type ReviewStatus } from '../editor/review-field'
import type { ReviewNotice } from '../editor/review-runtime'
import { noticeMessage } from '../suggestions/notice'
import type { SuggestionNotice } from '../suggestions/types'
import { EditorPane } from './EditorPane'
import { Hint } from './Hint'
import { MissingKeyBanner } from './MissingKeyBanner'
import { ReviewToolbar } from './ReviewToolbar'
import { Toast, type ToastMessage } from './Toast'

type AppProps = {
  readonly initialDoc: string
  readonly hasApiKey: boolean
  readonly onDocumentChange: (doc: string) => void
}

export function App({ initialDoc, hasApiKey, onDocumentChange }: AppProps) {
  const [toast, setToast] = useState<ToastMessage | null>(null)
  const [review, setReview] = useState<ReviewStatus>(idleReviewStatus)
  const [controls, setControls] = useState<ReviewControls | null>(null)
  const toastId = useRef(0)
  const headerRef = useRef<HTMLElement>(null)
  const getTopInset = useCallback(
    () => headerRef.current?.getBoundingClientRect().bottom ?? 0,
    [],
  )
  const dismissToast = useCallback(() => setToast(null), [])

  const showToast = useCallback(
    (text: string, retry?: () => void) =>
      setToast({
        id: ++toastId.current,
        text,
        ...(retry && { action: { label: 'Retry', run: retry } }),
      }),
    [],
  )
  const onNotice = useCallback(
    (notice: SuggestionNotice) => showToast(noticeMessage(notice.kind)),
    [showToast],
  )
  const onReviewNotice = useCallback(
    (notice: ReviewNotice) => showToast(notice.text, notice.retry),
    [showToast],
  )

  return (
    <div className="min-h-screen">
      <header ref={headerRef} className="sticky top-0 z-30 bg-canvas">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-between gap-x-6 gap-y-3 px-6 pt-6 pb-3">
          <h1 className="font-display font-semibold text-2xl text-ink-strong tracking-wide">
            Chiri
          </h1>
          <div className="flex flex-wrap items-center justify-end gap-x-5 gap-y-2">
            <Hint />
            <ReviewToolbar status={review} controls={controls} />
          </div>
        </div>
      </header>
      <main className="mx-auto max-w-3xl px-6 pt-4 pb-40">
        <EditorPane
          initialDoc={initialDoc}
          onChange={onDocumentChange}
          onNotice={onNotice}
          onReviewStatus={setReview}
          onReviewNotice={onReviewNotice}
          onReviewControls={setControls}
          getTopInset={getTopInset}
        />
      </main>
      <Toast message={toast} onDismiss={dismissToast} />
      {hasApiKey ? null : <MissingKeyBanner />}
    </div>
  )
}
import { useEffect, useRef } from 'react'
import { appendReviewDrop } from '../ai/dev-log'
import { createLazyModelClient } from '../ai/lazy-client'
import { createEditorView } from '../editor/create-editor-view'
import {
  bindReviewControls,
  type ReviewControls,
} from '../editor/review-controls'
import type { ReviewStatus } from '../editor/review-field'
import type { ReviewNotice } from '../editor/review-runtime'
import { suggestionExtensions } from '../editor/suggestions'
import { spaceBelowHeader } from '../editor/tooltip-space'
import type { SuggestionNotice } from '../suggestions/types'

type EditorPaneProps = {
  readonly initialDoc: string
  readonly onChange: (doc: string) => void
  readonly onNotice: (notice: SuggestionNotice) => void
  readonly onReviewStatus: (status: ReviewStatus) => void
  readonly onReviewNotice: (notice: ReviewNotice) => void
  readonly onReviewControls: (controls: ReviewControls | null) => void
  readonly getTopInset: () => number
}

export function EditorPane({
  initialDoc,
  onChange,
  onNotice,
  onReviewStatus,
  onReviewNotice,
  onReviewControls,
  getTopInset,
}: EditorPaneProps) {
  const parentRef = useRef<HTMLDivElement>(null)
  const initialDocRef = useRef(initialDoc)
  const handlersRef = useRef({
    onChange,
    onNotice,
    onReviewStatus,
    onReviewNotice,
    onReviewControls,
    getTopInset,
  })

  useEffect(() => {
    handlersRef.current = {
      onChange,
      onNotice,
      onReviewStatus,
      onReviewNotice,
      onReviewControls,
      getTopInset,
    }
  }, [
    onChange,
    onNotice,
    onReviewStatus,
    onReviewNotice,
    onReviewControls,
    getTopInset,
  ])

  useEffect(() => {
    const parent = parentRef.current
    if (!parent) return undefined
    const view = createEditorView({
      parent,
      doc: initialDocRef.current,
      onChange: (doc) => handlersRef.current.onChange(doc),
      extensions: [
        spaceBelowHeader(() => handlersRef.current.getTopInset()),
        ...suggestionExtensions({
          client: createLazyModelClient(() =>
            import('../ai/browser-client').then((module) =>
              module.createBrowserModelClient(),
            ),
          ),
          onNotice: (notice) => handlersRef.current.onNotice(notice),
          review: {
            onStatus: (status) => handlersRef.current.onReviewStatus(status),
            onNotice: (notice) => handlersRef.current.onReviewNotice(notice),
            ...(import.meta.env.DEV && {
              onDrop: (drop) => appendReviewDrop(window, drop),
            }),
          },
        }),
      ],
    })
    handlersRef.current.onReviewControls(bindReviewControls(view))
    return () => {
      handlersRef.current.onReviewControls(null)
      view.destroy()
    }
  }, [])

  return <div ref={parentRef} />
}
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands'
import { markdown, markdownLanguage } from '@codemirror/lang-markdown'
import { syntaxHighlighting } from '@codemirror/language'
import type { Extension } from '@codemirror/state'
import { drawSelection, EditorView, keymap } from '@codemirror/view'
import { codeBlockLines } from './code-block-lines'
import { editorTheme, markdownHighlightStyle } from './theme'

export const baseExtensions: readonly Extension[] = [
  history(),
  drawSelection(),
  EditorView.lineWrapping,
  markdown({ base: markdownLanguage }),
  syntaxHighlighting(markdownHighlightStyle),
  codeBlockLines,
  keymap.of([...defaultKeymap, ...historyKeymap]),
  editorTheme,
  EditorView.contentAttributes.of({ 'aria-label': 'Document' }),
]
import type { Extension } from '@codemirror/state'
import { EditorView, tooltips } from '@codemirror/view'

type Viewport = { readonly width: number; readonly height: number }

export type TooltipSpace = {
  readonly top: number
  readonly left: number
  readonly right: number
  readonly bottom: number
}

export const spaceBelow = (
  inset: number,
  viewport: Viewport,
): TooltipSpace => ({
  top: Math.max(0, inset),
  left: 0,
  right: viewport.width,
  bottom: viewport.height,
})

const viewportOf = (view: EditorView): Viewport => {
  const root = view.dom.ownerDocument.documentElement
  return { width: root.clientWidth, height: root.clientHeight }
}

export const spaceBelowHeader = (getInset: () => number): Extension => [
  tooltips({
    tooltipSpace: (view) => spaceBelow(getInset(), viewportOf(view)),
  }),
  EditorView.scrollMargins.of((view) => ({
    top: spaceBelow(getInset(), viewportOf(view)).top,
  })),
]
import { StateEffect, StateField } from '@codemirror/state'
import { type EditorView, ViewPlugin } from '@codemirror/view'
import type { SuggestionId } from '../suggestions/types'

export type InteractionState = {
  readonly pointerDown: boolean
  readonly focused: boolean
  readonly hoveredId: SuggestionId | null
}

export const pointerEffect = StateEffect.define<boolean>()
export const focusEffect = StateEffect.define<boolean>()
export const hoverEffect = StateEffect.define<SuggestionId | null>()

const applyInteraction = (
  state: InteractionState,
  effect: StateEffect<unknown>,
): InteractionState => {
  if (effect.is(pointerEffect)) return { ...state, pointerDown: effect.value }
  if (effect.is(focusEffect)) return { ...state, focused: effect.value }
  if (effect.is(hoverEffect)) return { ...state, hoveredId: effect.value }
  return state
}

export const interactionField = StateField.define<InteractionState>({
  create: () => ({ pointerDown: false, focused: false, hoveredId: null }),
  update: (value, transaction) =>
    transaction.effects.reduce(applyInteraction, value),
})

const suggestionIdOf = (target: EventTarget | null): SuggestionId | null =>
  target instanceof Element
    ? (target.closest<HTMLElement>('[data-suggestion-id]')?.dataset
        .suggestionId ?? null)
    : null

const interactionPlugin = ViewPlugin.define((view: EditorView) => {
  const setHover = (id: SuggestionId | null): void => {
    if (view.state.field(interactionField).hoveredId !== id)
      view.dispatch({ effects: hoverEffect.of(id) })
  }
  const onMouseDown = (): void =>
    view.dispatch({ effects: pointerEffect.of(true) })
  const onMouseUp = (): void => {
    if (view.state.field(interactionField).pointerDown)
      view.dispatch({ effects: pointerEffect.of(false) })
  }
  const onMouseOver = (event: MouseEvent): void =>
    setHover(suggestionIdOf(event.target))
  const onMouseLeave = (): void => setHover(null)
  const setFocused = (focused: boolean): void =>
    queueMicrotask(() => {
      if (
        view.dom.isConnected &&
        view.state.field(interactionField).focused !== focused
      )
        view.dispatch({ effects: focusEffect.of(focused) })
    })
  const onFocusIn = (): void => setFocused(true)
  const onFocusOut = (event: FocusEvent): void => {
    const next = event.relatedTarget
    if (!(next instanceof Node && view.dom.contains(next))) setFocused(false)
  }

  view.contentDOM.addEventListener('mousedown', onMouseDown)
  view.contentDOM.addEventListener('mouseover', onMouseOver)
  view.contentDOM.addEventListener('mouseleave', onMouseLeave)
  view.dom.addEventListener('focusin', onFocusIn)
  view.dom.addEventListener('focusout', onFocusOut)
  document.addEventListener('mouseup', onMouseUp)

  return {
    destroy: () => {
      view.contentDOM.removeEventListener('mousedown', onMouseDown)
      view.contentDOM.removeEventListener('mouseover', onMouseOver)
      view.contentDOM.removeEventListener('mouseleave', onMouseLeave)
      view.dom.removeEventListener('focusin', onFocusIn)
      view.dom.removeEventListener('focusout', onFocusOut)
      document.removeEventListener('mouseup', onMouseUp)
    },
  }
})

export const interactionState = [interactionField, interactionPlugin]
