(async () => {
  const f = await import('/src/editor/suggestion-field.ts');
  const i = await import('/src/suggestions/instruction.ts');
  const view = window.__dbgView;
  const doc = view.state.doc.toString();
  const add = (id, original, replacement, rationale, source) => {
    const from = doc.indexOf(original);
    view.dispatch({ effects: f.beginEffect.of({ id, from, to: from + original.length, source, original, instruction: i.quickActionInstruction('clearer') }) });
    view.dispatch({ effects: f.resolveEffect.of({ id, result: { replacement, rationale, unchanged: false } }) });
    return from;
  };
  const para3 = doc.split('\n\n').find(p => p.startsWith('Honestly'));
  const a = add('s1', 'hardened into a habit nobody questions', 'become an established practice', 'Neutral wording; the original sounds dismissive of the team.', 'selection');
  const b = add('s2', para3, 'The old freeze was frustrating for many of us. As we remove it, please avoid deploying a large change at 5pm on Friday and then leaving for the weekend.', 'Keeps the request but drops the slang for a team-wide memo.', 'block');
  window.__dbgModules = { f, i };
  const card = document.querySelector('.cm-ai-card-active');
  return { a, b, cardClass: card?.className, placement: view.state.field ? undefined : null };
})()
EOF

