.cm-ai-suggestion {
  background: rgb(241 241 243 / 0.03);
}

.cm-ai-suggestion.cm-ai-active {
  background: var(--color-fill);
}

.cm-ai-refine-failed {
  text-decoration: underline dotted var(--color-danger);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.cm-ai-deleted {
  color: var(--color-ink-faint);
  text-decoration: line-through;
  text-decoration-color: var(--color-ink-faint);
}

.cm-ai-inserted,
.cm-ai-replacement ins {
  color: var(--color-accent-soft);
  background: var(--color-accent-tint);
  text-decoration: none;
  white-space: pre-wrap;
}

.cm-ai-inserted-separated {
  margin-left: 0.3em;
}

.cm-ai-replacement {
  margin: 0.2rem 0 0.9rem;
  padding: 0.35rem 0.75rem;
  background: var(--color-accent-tint);
  color: var(--color-accent-soft);
  white-space: pre-wrap;
}

.cm-ai-replacement ins {
  background: transparent;
}

.cm-ai-target-preview {
  background: var(--color-accent-tint);
}

.cm-ai-pending,
.cm-ai-refining {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    transparent 38%,
    var(--color-shimmer) 50%,
    transparent 62%,
    transparent 100%
  );
  background-size: 300% 100%;
  animation: cm-ai-shimmer 1.8s linear infinite;
}

@keyframes cm-ai-shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cm-ai-pending,
